import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../core/constants/app_colors.dart';
import '../../models/booking_model.dart';
import '../../models/review_model.dart';
import '../../viewmodels/booking_viewmodel.dart';

class BookingTrackerScreen extends StatefulWidget { const BookingTrackerScreen({super.key}); @override State<BookingTrackerScreen> createState() => _BookingTrackerScreenState(); }
class _BookingTrackerScreenState extends State<BookingTrackerScreen> {
  @override void initState() { super.initState(); WidgetsBinding.instance.addPostFrameCallback((_) => context.read<BookingViewModel>().loadBookings()); }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Your bookings')), body: Consumer<BookingViewModel>(builder: (context, vm, _) => vm.isLoading ? const Center(child: CircularProgressIndicator()) : vm.bookings.isEmpty ? const Center(child: Text('No bookings yet')) : ListView(padding: const EdgeInsets.all(18), children: vm.bookings.map((b) => Card(elevation: 0, child: Padding(padding: const EdgeInsets.all(18), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(b.gigTitle, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 18)), const SizedBox(height: 4), Text('${b.provider} · ${b.date}', style: const TextStyle(color: Colors.blueGrey)), const SizedBox(height: 20), _StatusTrack(status: b.status), const SizedBox(height: 18), if (b.status != BookingStatus.completed) SizedBox(width: double.infinity, child: FilledButton(onPressed: () async { await vm.advance(b.id); if (b.status == BookingStatus.inProgress && context.mounted) _reviewDialog(context, b.id); }, child: Text(b.status == BookingStatus.pending ? 'Start service' : 'Mark completed'))) else Align(alignment: Alignment.centerRight, child: TextButton.icon(onPressed: () => _reviewDialog(context, b.id), icon: const Icon(Icons.star), label: const Text('Leave a review')))])))).toList())));
  void _reviewDialog(BuildContext context, String id) { int rating = 5; final comment = TextEditingController(); showDialog(context: context, builder: (dialogContext) => StatefulBuilder(builder: (context, setState) => AlertDialog(title: const Text('Rate your experience'), content: Column(mainAxisSize: MainAxisSize.min, children: [Row(mainAxisAlignment: MainAxisAlignment.center, children: List.generate(5, (i) => IconButton(onPressed: () => setState(() => rating = i + 1), icon: Icon(Icons.star, color: i < rating ? Colors.amber : Colors.grey.shade300)))), TextField(controller: comment, decoration: const InputDecoration(hintText: 'Share a few words (optional)'))]), actions: [TextButton(onPressed: () => Navigator.pop(dialogContext), child: const Text('Cancel')), FilledButton(onPressed: () { context.read<BookingViewModel>().review(ReviewModel(bookingId: id, rating: rating, comment: comment.text)); Navigator.pop(dialogContext); }, child: const Text('Submit'))]))); }
}

class _StatusTrack extends StatelessWidget { const _StatusTrack({required this.status}); final BookingStatus status;
  @override Widget build(BuildContext context) { final current = status.index; const labels = ['Pending', 'In progress', 'Completed']; const colors = [AppColors.pending, AppColors.inProgress, AppColors.completed]; return Row(children: List.generate(5, (i) { if (i.isOdd) return Expanded(child: Container(height: 2, color: current >= i ~/ 2 + 1 ? AppColors.completed : const Color(0xFFE2E8F0))); final step = i ~/ 2; return Column(children: [CircleAvatar(radius: 15, backgroundColor: current >= step ? colors[step] : const Color(0xFFE2E8F0), child: Icon(current > step ? Icons.check : Icons.circle, color: Colors.white, size: 13)), const SizedBox(height: 6), Text(labels[step], style: const TextStyle(fontSize: 10))]); })); }
}
